import { build } from "esbuild";
import { readFile, writeFile, mkdir, rm, copyFile } from "node:fs/promises";
import { execFileSync } from "node:child_process";

await mkdir("src/generated", { recursive: true });
const client = await build({
    entryPoints: ["src/client/viewer.ts"],
    bundle: true,
    write: false,
    format: "esm",
    target: "es2022",
    minify: true,
});
const css = await readFile("src/client/viewer.css", "utf8");
await writeFile(
    "src/generated/viewer.ts",
    "// Generated by scripts/build.mjs. Do not edit.\nexport const viewerJs: string = " +
        JSON.stringify(client.outputFiles[0].text) +
        ";\nexport const viewerCss: string = " +
        JSON.stringify(css) +
        ";\n",
);
await rm("dist", { recursive: true, force: true });
execFileSync(
    process.execPath,
    ["node_modules/typescript/bin/tsc", "--project", "tsconfig.build.json"],
    { stdio: "inherit" },
);
if (process.argv.includes("--package")) {
    await rm("tmp/package", { recursive: true, force: true });
    await mkdir("tmp/package", { recursive: true });
    const { cp } = await import("node:fs/promises");
    await cp("dist", "tmp/package/dist", { recursive: true });
    const pkg = JSON.parse(await readFile("package.json", "utf8"));
    delete pkg.devDependencies;
    delete pkg.scripts;
    delete pkg.packageManager;
    await writeFile("tmp/package/package.json", JSON.stringify(pkg, null, 2));
    for (const name of ["README.md", "llms.txt", "LICENSE"])
        await copyFile(name, "tmp/package/" + name);
}
